import '.:Accueil.css';

export default function Accueil() {
    return (
        <>
            <section class="hero">
                <div class="wrap">
                    <div class="status"><span class="dot"></span> Disponible pour un stage</div>
                    <h1>Antoine Priam</h1>
                    <p class="role">Développeur web &amp; étudiant BTS SIO — à l'aise aussi bien sur une interface React que sur une baie de brassage.</p>
                    <p class="pitch">Je viens d'un parcours en systèmes numériques, entre réseaux, maintenance informatique et développement front-end. J'aime comprendre une infrastructure de bout en bout, du câblage jusqu'à l'interface que l'utilisateur touche.</p>
                    <div class="cta-row">
                    <a class="btn btn-primary" href="#projects">Voir mes projets</a>
                    <a class="btn btn-ghost" href="#contact">Me contacter</a>
                    <a class="btn btn-ghost" href="E5-Synthèse.pdf" download>Télécharger la grille de compétences</a>
                    </div>
                </div>
            </section>
        </>
    );
}
